
import type { MoneyValueInput } from './MoneyValueInput.js';

export type InvoicePaymentAttemptInput = { /** RFC3339 timestamp. Format: date-time. */ "canceled_at"?: string | globalThis.Date; /** RFC3339 timestamp. Format: date-time. */ "cancellation_requested_at"?: string | globalThis.Date; "checkout_session_id"?: string; "expected_amount_money": MoneyValueInput; /** RFC3339 timestamp. Format: date-time. */ "expected_settlement_at"?: string | globalThis.Date; /** RFC3339 timestamp. Format: date-time. */ "expires_at"?: string | globalThis.Date; /** Flint-normalized invoice payment attempt failure code. Unknown provider values are returned as payment_failed. */ "failure_code"?: "card_declined" | "insufficient_funds" | "bank_account_closed" | "bank_account_not_found" | "bank_debit_not_authorized" | "bank_account_restricted" | "bank_debit_limit_exceeded" | "authentication_required" | "payment_blocked" | "expired_card" | "incorrect_cvc" | "processing_error" | "payment_method_unavailable" | "payment_method_declined" | "payment_not_completed" | "payment_action_expired" | "payment_method_temporarily_unavailable" | "payment_failed"; /** Flint-authored invoice payment attempt failure message. This is stable explanatory text, not a raw provider message. */ "failure_message"?: string; "invoice_id": string; "invoice_payment_attempt_id": string; "invoice_schedule_entry_id"?: string; "payment_intent_id"?: string; "rail": "card" | "ach_debit" | "manual"; /** RFC3339 timestamp. Format: date-time. */ "settled_at"?: string | globalThis.Date; /** RFC3339 timestamp. Format: date-time. */ "started_at"?: string | globalThis.Date; "status": "open" | "settled" | "failed" | "canceled" | "expired" | "processing"; /** RFC3339 timestamp. Format: date-time. */ "updated_at"?: string | globalThis.Date; };
